export { LineChart, type LineChartProps } from "./line";
export { AreaChart, type AreaChartProps } from "./area";
export { BarChart, type BarChartProps, type BarOrientation } from "./bar";
export { ScatterChart, type ScatterChartProps } from "./scatter";
export { Donut, Share, type DonutProps, type ShareProps, type ShareSlice } from "./donut";
export { Histogram, type HistogramProps, type HistogramBin } from "./histogram";
export { SmallMultiples, type SmallMultiplesProps, type SmallMultiple } from "./multiples";
export { Sparkline, type SparklineProps } from "./sparkline";
export type { ChartSeries, ChartAnnotation, ChartPoint } from "./frame";

import * as React from "react";
import {
  ChartField,
  ChartTip,
  LINE_CLASS,
  LegendSwatch,
  MAX_SERIES,
  PLOT,
  SrTable,
  defaultFormat,
  niceMax,
  stackedRows,
  ticksFor,
  type ChartAnnotation,
  type ChartSeries,
} from "./frame";

export interface LineChartProps extends React.HTMLAttributes<HTMLDivElement> {
  series: ChartSeries[];
  labels?: string[];
  height?: number;
  /** Fill under the first series. Prefer AreaChart for a dedicated area. */
  area?: boolean;
  stacked?: boolean;
  inverted?: boolean;
  grid?: boolean;
  ticks?: number;
  unit?: string;
  yLabel?: string;
  xLabel?: string;
  annotations?: ChartAnnotation[];
  domain?: [number, number];
  spot?: boolean | string;
  valueFormat?: (value: number) => string;
}

export function LineChart({
  series,
  labels,
  height = 204,
  area,
  stacked,
  inverted,
  grid = true,
  ticks = 4,
  unit,
  yLabel,
  xLabel,
  annotations,
  domain,
  spot,
  valueFormat,
  className,
  ...props
}: LineChartProps) {
  const shown = series.slice(0, MAX_SERIES);
  const n = Math.max(1, ...shown.map((s) => s.values.length));
  const stacks = stacked ? stackedRows(shown) : null;
  const rawMax = stacks
    ? Math.max(...stacks.map((row) => row[row.length - 1] ?? 0))
    : Math.max(0, ...shown.flatMap((s) => s.values));
  const max = domain?.[1] ?? niceMax(rawMax);
  const min = domain?.[0] ?? 0;
  const span = max - min || 1;
  const format = valueFormat ?? ((v: number) => defaultFormat(v, unit));
  const [hover, setHover] = React.useState<number | null>(null);
  const overlayRef = React.useRef<SVGRectElement>(null);

  const { W, ML, MR, MT, MB } = PLOT;
  const plotW = W - ML - MR;
  const plotH = height - MT - MB;
  const x = (i: number) => ML + (n <= 1 ? 0 : (i / (n - 1)) * plotW);
  const y = (v: number) => {
    const t = (v - min) / span;
    return inverted ? MT + t * plotH : MT + plotH - t * plotH;
  };
  const path = (values: number[]) => values.map((v, i) => `${i === 0 ? "M" : "L"}${x(i)} ${y(v)}`).join(" ");
  const tickVals = ticksFor(max, ticks);
  const tickLabels = labels ?? Array.from({ length: n }, (_, i) => `${i + 1}`);

  const locate = (clientX: number): number | null => {
    const rect = overlayRef.current?.getBoundingClientRect();
    if (!rect || rect.width === 0) return null;
    const ratio = Math.min(1, Math.max(0, (clientX - rect.left) / rect.width));
    return Math.round(ratio * (n - 1));
  };

  return (
    <ChartField spot={spot} className={className} {...props}>
      {(yLabel || xLabel) && (
        <div className="rs-chart-head">
          {yLabel ? <p className="rs-chart-title">{yLabel}</p> : <span />}
          {xLabel ? <p className="rs-chart-title">{xLabel}</p> : null}
        </div>
      )}
      <svg viewBox={`0 0 ${W} ${height}`} role="img" aria-label={`Line chart, ${shown.map((s) => s.name).join(" and ")}`}>
        <g className="rs-chart-plot">
          {grid &&
            tickVals.map((t) => (
              <g key={t}>
                <line className="rs-chart-grid" x1={ML} x2={W - MR} y1={y(t)} y2={y(t)} />
                <text className="rs-chart-axis" x={ML - 6} y={y(t) + 3.5} textAnchor="end">
                  {format(t)}
                </text>
              </g>
            ))}
          <line className="rs-chart-baseline" x1={ML} x2={W - MR} y1={y(min)} y2={y(min)} />
          {area && shown[0] && !stacked && (
            <path
              className={spot ? "rs-chart-area-spot" : "rs-chart-area"}
              d={`${path(shown[0].values)} L${x(n - 1)} ${y(min)} L${x(0)} ${y(min)} Z`}
            />
          )}
          {stacked && stacks
            ? shown.map((s, si) => {
                const top = stacks.map((row) => row[si] ?? 0);
                return (
                  <path
                    key={s.name}
                    className={spot && si === 0 ? "rs-chart-line rs-chart-line-spot" : LINE_CLASS[si]}
                    d={path(top)}
                  />
                );
              })
            : shown.map((s, si) => (
                <path
                  key={s.name}
                  className={spot && si === 0 ? "rs-chart-line rs-chart-line-spot" : LINE_CLASS[si]}
                  d={path(s.values)}
                />
              ))}
          {annotations?.map((a) => (
            <g key={`${a.at}-${a.label}`}>
              <line className="rs-chart-cursor" x1={x(a.at)} x2={x(a.at)} y1={MT} y2={y(min)} />
              <text className="rs-chart-ann" x={x(a.at) + 4} y={MT + 10}>
                {a.label}
              </text>
            </g>
          ))}
          {hover != null && (
            <g>
              <line className="rs-chart-cursor" x1={x(hover)} x2={x(hover)} y1={MT} y2={y(min)} />
              {shown.map((s, si) => (
                <circle
                  key={si}
                  className="rs-chart-dot"
                  cx={x(hover)}
                  cy={y(stacked && stacks ? (stacks[hover]?.[si] ?? 0) : (s.values[hover] ?? 0))}
                  r={3}
                />
              ))}
            </g>
          )}
          <text className="rs-chart-axis" x={ML} y={height - 4} textAnchor="start">
            {tickLabels[0]}
          </text>
          <text className="rs-chart-axis" x={W - MR} y={height - 4} textAnchor="end">
            {tickLabels[n - 1]}
          </text>
          <rect
            ref={overlayRef}
            x={ML}
            y={0}
            width={plotW}
            height={height}
            fill="transparent"
            onMouseMove={(e) => setHover(locate(e.clientX))}
            onMouseLeave={() => setHover(null)}
          />
        </g>
      </svg>
      {hover != null && (
        <ChartTip
          left={`${(x(hover) / W) * 100}%`}
          top={`${(MT / height) * 100}%`}
          label={tickLabels[hover] ?? ""}
          rows={shown.map((s) => ({ name: s.name, value: format(s.values[hover] ?? 0) }))}
        />
      )}
      {shown.length > 1 && (
        <div className="rs-chart-legend">
          {shown.map((s, si) => (
            <span key={s.name} className="rs-chart-legend-item">
              <LegendSwatch seriesIndex={si} spot={Boolean(spot)} />
              {s.name}
            </span>
          ))}
        </div>
      )}
      <SrTable caption="Chart data" labels={tickLabels} series={shown} />
    </ChartField>
  );
}

import * as React from "react";
import { LineChart, type LineChartProps } from "./line";

export type AreaChartProps = Omit<LineChartProps, "area">;

/** Filled field. Same law as the line: hairlines, texture, one optional spot. */
export function AreaChart(props: AreaChartProps) {
  return <LineChart {...props} area />;
}

import * as React from "react";
import { cx } from "../cx";
import {
  ChartField,
  ChartTip,
  PLOT,
  SrTable,
  defaultFormat,
  niceMax,
  stackedRows,
  ticksFor,
  type ChartSeries,
} from "./frame";

export type BarOrientation = "vertical" | "horizontal";

export interface BarChartProps extends React.HTMLAttributes<HTMLDivElement> {
  data?: Array<{ label: string; value: number }>;
  series?: ChartSeries[];
  labels?: string[];
  height?: number;
  orientation?: BarOrientation;
  stacked?: boolean;
  inverted?: boolean;
  grid?: boolean;
  ticks?: number;
  unit?: string;
  yLabel?: string;
  spot?: boolean | string;
  valueFormat?: (value: number) => string;
}

export function BarChart({
  data,
  series,
  labels,
  height = 204,
  orientation = "vertical",
  stacked,
  inverted,
  grid = true,
  ticks = 4,
  unit,
  yLabel,
  spot,
  valueFormat,
  className,
  ...props
}: BarChartProps) {
  const fromData: ChartSeries[] = data ? [{ name: "Value", values: data.map((d) => d.value) }] : [];
  const shown = (series ?? fromData).slice(0, 4);
  const tickLabels = labels ?? data?.map((d) => d.label) ?? shown[0]?.values.map((_, i) => `${i + 1}`) ?? [];
  const n = tickLabels.length;
  const stacks = stacked && shown.length > 1 ? stackedRows(shown) : null;
  const rawMax = stacks
    ? Math.max(...stacks.map((row) => row[row.length - 1] ?? 0))
    : Math.max(0, ...shown.flatMap((s) => s.values));
  const max = niceMax(rawMax);
  const format = valueFormat ?? ((v: number) => defaultFormat(v, unit));
  const [hover, setHover] = React.useState<number | null>(null);

  const { W, ML, MR, MT, MB } = PLOT;
  const plotW = W - ML - MR;
  const plotH = height - MT - MB;
  const horizontal = orientation === "horizontal";
  const band = (horizontal ? plotH : plotW) / Math.max(1, n);
  const barThick = Math.min(8, Math.max(2, band - 1));
  const inset = (band - barThick) / 2;
  const yV = (v: number) => {
    const t = v / max;
    return inverted ? MT + t * plotH : MT + plotH - t * plotH;
  };
  const xV = (v: number) => ML + (v / max) * plotW;
  const tickVals = ticksFor(max, ticks);
  const labelEvery = Math.ceil(n / 8);

  return (
    <ChartField spot={spot} className={className} {...props}>
      {yLabel && (
        <div className="rs-chart-head">
          <p className="rs-chart-title">{yLabel}</p>
        </div>
      )}
      <svg viewBox={`0 0 ${W} ${height}`} role="img" aria-label="Bar chart">
        <g className="rs-chart-plot">
          {grid &&
            tickVals.map((t) =>
              horizontal ? (
                <g key={t}>
                  <line className="rs-chart-grid" x1={xV(t)} x2={xV(t)} y1={MT} y2={height - MB} />
                  <text className="rs-chart-axis" x={xV(t)} y={height - 4} textAnchor="middle">
                    {format(t)}
                  </text>
                </g>
              ) : (
                <g key={t}>
                  <line className="rs-chart-grid" x1={ML} x2={W - MR} y1={yV(t)} y2={yV(t)} />
                  <text className="rs-chart-axis" x={ML - 6} y={yV(t) + 3.5} textAnchor="end">
                    {format(t)}
                  </text>
                </g>
              ),
            )}
          {tickLabels.map((label, i) => {
            const values = shown.map((s) => s.values[i] ?? 0);
            if (horizontal) {
              const y0 = MT + i * band + inset;
              if (stacks) {
                let prev = 0;
                return shown.map((s, si) => {
                  const v = s.values[i] ?? 0;
                  const x1 = xV(prev);
                  const x2 = xV(prev + v);
                  prev += v;
                  return (
                    <rect
                      key={`${label}-${s.name}`}
                      className={cx(
                        "rs-chart-bar",
                        spot && si === 0 && "rs-chart-bar-spot",
                        hover != null && hover !== i && "rs-chart-bar-muted",
                      )}
                      x={x1}
                      y={y0}
                      width={Math.max(0, x2 - x1)}
                      height={barThick}
                      onMouseEnter={() => setHover(i)}
                      onMouseLeave={() => setHover(null)}
                    />
                  );
                });
              }
              const v = values[0] ?? 0;
              return (
                <rect
                  key={label}
                  className={cx("rs-chart-bar", spot && "rs-chart-bar-spot", hover != null && hover !== i && "rs-chart-bar-muted")}
                  x={ML}
                  y={y0}
                  width={Math.max(0, xV(v) - ML)}
                  height={barThick}
                  onMouseEnter={() => setHover(i)}
                  onMouseLeave={() => setHover(null)}
                />
              );
            }
            const x0 = ML + i * band + inset;
            if (stacks) {
              let prev = 0;
              return shown.map((s, si) => {
                const v = s.values[i] ?? 0;
                const y1 = yV(prev + v);
                const y2 = yV(prev);
                prev += v;
                return (
                  <rect
                    key={`${label}-${s.name}`}
                    className={cx(
                      "rs-chart-bar",
                      spot && si === 0 && "rs-chart-bar-spot",
                      hover != null && hover !== i && "rs-chart-bar-muted",
                    )}
                    x={x0}
                    y={y1}
                    width={barThick}
                    height={Math.max(0, y2 - y1)}
                    onMouseEnter={() => setHover(i)}
                    onMouseLeave={() => setHover(null)}
                  />
                );
              });
            }
            const v = values[0] ?? 0;
            return (
              <rect
                key={label}
                className={cx("rs-chart-bar", spot && "rs-chart-bar-spot", hover != null && hover !== i && "rs-chart-bar-muted")}
                x={x0}
                y={yV(v)}
                width={barThick}
                height={Math.max(0, yV(0) - yV(v))}
                onMouseEnter={() => setHover(i)}
                onMouseLeave={() => setHover(null)}
              />
            );
          })}
          <line
            className="rs-chart-baseline"
            x1={ML}
            x2={horizontal ? ML : W - MR}
            y1={horizontal ? MT : yV(0)}
            y2={horizontal ? height - MB : yV(0)}
          />
          {tickLabels.map(
            (label, i) =>
              i % labelEvery === 0 && (
                <text
                  key={label}
                  className="rs-chart-axis"
                  x={horizontal ? ML - 6 : ML + i * band + band / 2}
                  y={horizontal ? MT + i * band + band / 2 + 3 : height - 4}
                  textAnchor={horizontal ? "end" : "middle"}
                >
                  {label}
                </text>
              ),
          )}
        </g>
      </svg>
      {hover != null && tickLabels[hover] && (
        <ChartTip
          left={horizontal ? "50%" : `${((ML + hover * band + band / 2) / W) * 100}%`}
          top={horizontal ? `${((MT + hover * band) / height) * 100}%` : `${(yV(shown[0]?.values[hover] ?? 0) / height) * 100}%`}
          label={tickLabels[hover]}
          rows={shown.map((s) => ({ name: shown.length > 1 ? s.name : undefined, value: format(s.values[hover] ?? 0) }))}
        />
      )}
      <SrTable caption="Chart data" labels={tickLabels} series={shown} />
    </ChartField>
  );
}

import * as React from "react";
import {
  ChartField,
  ChartTip,
  LegendSwatch,
  PLOT,
  SrTable,
  defaultFormat,
  ticksBetween,
  type ChartAnnotation,
  type ChartPoint,
} from "./frame";

export type ScatterChartProps = React.HTMLAttributes<HTMLDivElement> & {
  points: ChartPoint[];
  height?: number;
  unit?: string;
  xLabel?: string;
  yLabel?: string;
  xDomain?: [number, number];
  yDomain?: [number, number];
  grid?: boolean;
  ticks?: number;
  annotations?: ChartAnnotation[];
  valueFormat?: (n: number) => string;
  spot?: boolean | string;
};

function extent(values: number[], pad = 0.08): [number, number] {
  const lo = Math.min(...values);
  const hi = Math.max(...values);
  const span = hi - lo || 1;
  return [lo - span * pad, hi + span * pad];
}

export function ScatterChart({
  points,
  height = 204,
  unit,
  xLabel,
  yLabel,
  xDomain,
  yDomain,
  grid = true,
  ticks = 4,
  annotations = [],
  valueFormat,
  className,
  spot,
  ...props
}: ScatterChartProps) {
  const format = valueFormat ?? ((v: number) => defaultFormat(v, unit));
  const [hover, setHover] = React.useState<number | null>(null);
  const { W, ML, MR, MT, MB } = PLOT;
  const plotW = W - ML - MR;
  const plotH = height - MT - MB;
  const xs = points.map((p) => p.x);
  const ys = points.map((p) => p.y);
  const [xMin, xMax] = xDomain ?? extent(xs);
  const [yMin, yMax] = yDomain ?? extent(ys);
  const yTicks = ticksBetween(yMin, yMax, ticks);
  const xTicks = ticksBetween(xMin, xMax, ticks);
  const toX = (x: number) => ML + ((x - xMin) / (xMax - xMin || 1)) * plotW;
  const toY = (y: number) => MT + plotH - ((y - yMin) / (yMax - yMin || 1)) * plotH;
  const groups = [...new Set(points.map((p) => p.group).filter(Boolean))] as string[];
  const active = hover != null ? points[hover] : null;

  return (
    <ChartField spot={spot} className={className} {...props}>
      {(yLabel || xLabel) && (
        <div className="rs-chart-head">
          {yLabel ? <p className="rs-chart-title">{yLabel}</p> : <span />}
          {xLabel ? <p className="rs-chart-title">{xLabel}</p> : null}
        </div>
      )}
      <svg viewBox={`0 0 ${W} ${height}`} role="img" aria-label="Scatter">
        <g className="rs-chart-plot">
          {grid &&
            yTicks.map((t) => (
              <g key={`yg-${t}`}>
                <line className="rs-chart-grid" x1={ML} x2={W - MR} y1={toY(t)} y2={toY(t)} />
                <text className="rs-chart-axis" x={ML - 6} y={toY(t) + 3.5} textAnchor="end">
                  {format(t)}
                </text>
              </g>
            ))}
          {grid &&
            xTicks.map((t) => (
              <line key={`xg-${t}`} className="rs-chart-grid" x1={toX(t)} x2={toX(t)} y1={MT} y2={MT + plotH} />
            ))}
          <line className="rs-chart-baseline" x1={ML} x2={ML} y1={MT} y2={MT + plotH} />
          <line className="rs-chart-baseline" x1={ML} x2={W - MR} y1={MT + plotH} y2={MT + plotH} />
          {xTicks.map((t) => (
            <text key={`xl-${t}`} className="rs-chart-axis" x={toX(t)} y={height - 4} textAnchor="middle">
              {format(t)}
            </text>
          ))}
          {annotations.map((a) => (
            <g key={`${a.at}-${a.label}`}>
              <line className="rs-chart-cursor" x1={toX(a.at)} x2={toX(a.at)} y1={MT} y2={MT + plotH} />
              <text className="rs-chart-ann" x={toX(a.at) + 4} y={MT + 10}>
                {a.label}
              </text>
            </g>
          ))}
          {points.map((p, i) => (
            <circle
              key={i}
              className={spot ? "rs-chart-mark rs-chart-mark-spot" : "rs-chart-mark"}
              cx={toX(p.x)}
              cy={toY(p.y)}
              r={hover === i ? 3.5 : 2.25}
              onMouseEnter={() => setHover(i)}
              onMouseLeave={() => setHover(null)}
            />
          ))}
        </g>
      </svg>
      {active && (
        <ChartTip
          left={`${(toX(active.x) / W) * 100}%`}
          top={`${(toY(active.y) / height) * 100}%`}
          label={active.label ?? `${format(active.x)} · ${format(active.y)}`}
          rows={[{ name: active.group, value: format(active.y) }]}
        />
      )}
      {(groups.length > 0 || unit) && (
        <div className="rs-chart-legend" aria-hidden="true">
          {groups.map((g) => (
            <span key={g} className="rs-chart-legend-item">
              <LegendSwatch seriesIndex={0} spot={Boolean(spot)} />
              {g}
            </span>
          ))}
          {unit ? <span className="rs-chart-legend-item">{unit}</span> : null}
        </div>
      )}
      <SrTable
        caption="Scatter data"
        labels={points.map((p) => p.label ?? `${p.x}`)}
        series={[{ name: "y", values: points.map((p) => p.y) }]}
      />
    </ChartField>
  );
}

import * as React from "react";
import { cx } from "../cx";
import { ChartField, defaultFormat } from "./frame";

export interface DonutProps extends React.HTMLAttributes<HTMLDivElement> {
  value: number;
  max?: number;
  size?: number;
  label?: React.ReactNode;
  unit?: string;
  valueFormat?: (value: number) => string;
  spot?: boolean | string;
}

const R = 36;
const C = 2 * Math.PI * R;

export function Donut({
  value,
  max = 100,
  size = 184,
  label,
  unit,
  valueFormat,
  className,
  spot,
  ...props
}: DonutProps) {
  const format = valueFormat ?? ((v: number) => `${Math.round((v / max) * 100)}%`);
  const pct = Math.max(0, Math.min(1, max === 0 ? 0 : value / max));
  const caption = typeof label === "string" ? label : undefined;
  return (
    <ChartField spot={spot} className={cx("rs-chart-donut-wrap", className)} {...props}>
      <svg
        className="rs-chart-plot rs-chart-donut"
        width={size}
        height={size}
        viewBox="0 0 96 96"
        role="img"
        aria-label={`${format(value)}${caption ? ` ${caption}` : ""}`}
      >
        <circle className="rs-chart-donut-track" cx="48" cy="48" r={R} />
        <circle
          className="rs-chart-donut-value"
          cx="48"
          cy="48"
          r={R}
          strokeDasharray={`${pct * C} ${C}`}
          transform="rotate(-90 48 48)"
        />
        <text className="rs-chart-donut-label" x="48" y={caption ? 46 : 51} textAnchor="middle">
          {format(value)}
          {unit ? ` ${unit}` : ""}
        </text>
        {caption && (
          <text className="rs-chart-donut-caption" x="48" y="60" textAnchor="middle">
            {caption}
          </text>
        )}
      </svg>
      {label && !caption ? <p className="rs-chart-title">{label}</p> : null}
    </ChartField>
  );
}

export type ShareSlice = { label: string; value: number };

export interface ShareProps extends React.HTMLAttributes<HTMLDivElement> {
  slices: ShareSlice[];
  unit?: string;
  valueFormat?: (n: number) => string;
  spot?: boolean | string;
}

export function Share({
  slices,
  unit,
  valueFormat,
  className,
  spot,
  ...props
}: ShareProps) {
  const format = valueFormat ?? ((v: number) => defaultFormat(v, unit));
  const total = slices.reduce((s, x) => s + x.value, 0) || 1;
  return (
    <ChartField spot={spot} className={className} {...props}>
      <div className="rs-chart-share" role="img" aria-label="Share">
        {slices.map((s, i) => (
          <div
            key={s.label}
            className={cx("rs-chart-share-seg", i === 0 && "rs-chart-share-seg-spot")}
            style={{ flex: `${s.value} 1 0` }}
            title={`${s.label} ${format(s.value)}`}
          />
        ))}
      </div>
      <div className="rs-chart-legend" aria-hidden="true">
        {slices.map((s) => (
          <span key={s.label} className="rs-chart-legend-item">
            {s.label} {defaultFormat((s.value / total) * 100)}%
          </span>
        ))}
      </div>
    </ChartField>
  );
}

import * as React from "react";
import {
  ChartField,
  ChartTip,
  PLOT,
  SrTable,
  defaultFormat,
  niceMax,
  ticksFor,
} from "./frame";

export type HistogramBin = { label: string; count: number };

export interface HistogramProps extends React.HTMLAttributes<HTMLDivElement> {
  bins: HistogramBin[];
  height?: number;
  unit?: string;
  yLabel?: string;
  grid?: boolean;
  ticks?: number;
  valueFormat?: (n: number) => string;
  spot?: boolean | string;
}

export function Histogram({
  bins,
  height = 204,
  unit,
  yLabel,
  grid = true,
  ticks = 4,
  valueFormat,
  className,
  spot,
  ...props
}: HistogramProps) {
  const format = valueFormat ?? ((v: number) => defaultFormat(v, unit));
  const [hover, setHover] = React.useState<number | null>(null);
  const { W, ML, MR, MT, MB } = PLOT;
  const plotW = W - ML - MR;
  const plotH = height - MT - MB;
  const max = niceMax(Math.max(...bins.map((b) => b.count), 1));
  const yTicks = ticksFor(max, ticks);
  const gap = 1;
  const bw = (plotW - gap * Math.max(0, bins.length - 1)) / bins.length;
  const active = hover != null ? bins[hover] : null;

  return (
    <ChartField spot={spot} className={className} {...props}>
      {yLabel && (
        <div className="rs-chart-head">
          <p className="rs-chart-title">{yLabel}</p>
        </div>
      )}
      <svg viewBox={`0 0 ${W} ${height}`} role="img" aria-label="Histogram">
        <g className="rs-chart-plot">
          {grid &&
            yTicks.map((t) => {
              const y = MT + plotH - (t / max) * plotH;
              return (
                <g key={t}>
                  <line className="rs-chart-grid" x1={ML} x2={W - MR} y1={y} y2={y} />
                  <text className="rs-chart-axis" x={ML - 6} y={y + 3.5} textAnchor="end">
                    {format(t)}
                  </text>
                </g>
              );
            })}
          <line className="rs-chart-baseline" x1={ML} x2={W - MR} y1={MT + plotH} y2={MT + plotH} />
          {bins.map((b, i) => {
            const h = (b.count / max) * plotH;
            const x = ML + i * (bw + gap);
            const y = MT + plotH - h;
            return (
              <g key={b.label} onMouseEnter={() => setHover(i)} onMouseLeave={() => setHover(null)}>
                <rect className={spot ? "rs-chart-hist rs-chart-bar-spot" : "rs-chart-hist"} x={x} y={y} width={bw} height={h} />
                <text className="rs-chart-axis" x={x + bw / 2} y={height - 4} textAnchor="middle">
                  {b.label}
                </text>
              </g>
            );
          })}
        </g>
      </svg>
      {active && (
        <ChartTip
          left={`${((ML + (hover ?? 0) * (bw + gap) + bw / 2) / W) * 100}%`}
          top={`${((MT + plotH - (active.count / max) * plotH) / height) * 100}%`}
          label={active.label}
          rows={[{ value: format(active.count) }]}
        />
      )}
      {unit && (
        <div className="rs-chart-legend" aria-hidden="true">
          <span className="rs-chart-legend-item">{unit}</span>
        </div>
      )}
      <SrTable
        caption="Histogram"
        labels={bins.map((b) => b.label)}
        series={[{ name: "count", values: bins.map((b) => b.count) }]}
      />
    </ChartField>
  );
}

