import * as React from "react";
import { cx } from "../cx";
import { CROUWEL_SPOT } from "./frame";

export interface SparklineProps extends React.HTMLAttributes<HTMLSpanElement> {
  values: number[];
  width?: number;
  height?: number;
  spot?: boolean | string;
}

export function Sparkline({
  values,
  width = 120,
  height = 28,
  className,
  spot,
  style,
  ...props
}: SparklineProps) {
  const max = Math.max(...values);
  const min = Math.min(...values);
  const span = max - min || 1;
  const x = (i: number) => (i / Math.max(values.length - 1, 1)) * (width - 4) + 2;
  const y = (v: number) => 2 + (1 - (v - min) / span) * (height - 4);
  const d = values.map((v, i) => `${i === 0 ? "M" : "L"}${x(i)} ${y(v)}`).join(" ");
  const last = values[values.length - 1] ?? 0;
  const color = spot === true ? CROUWEL_SPOT : typeof spot === "string" ? spot : undefined;
  return (
    <span
      className={cx("rs-spark", className)}
      style={{
        ...(style as React.CSSProperties),
        ...(color ? ({ ["--rs-chart-spot" as string]: color } as React.CSSProperties) : null),
      }}
      {...props}
    >
      <svg width={width} height={height} viewBox={`0 0 ${width} ${height}`} role="img" aria-label={`Trend ending at ${last}`}>
        <path className={spot ? "rs-chart-line rs-chart-line-spot" : "rs-chart-line"} d={d} />
        <circle className="rs-chart-dot" cx={x(values.length - 1)} cy={y(last)} r={2} />
      </svg>
    </span>
  );
}

import * as React from "react";
import { cx } from "../cx";

export interface ChartSeries {
  name: string;
  values: number[];
}

export interface ChartAnnotation {
  /** Index into the labels (line/bar) or an x value (scatter). */
  at: number;
  label: string;
}

export interface ChartPoint {
  x: number;
  y: number;
  label?: string;
  group?: string;
}

export function ticksBetween(min: number, max: number, count = 4): number[] {
  const span = max - min || 1;
  return Array.from({ length: count }, (_, i) => min + ((i + 1) / count) * span);
}

export const LINE_CLASS = [
  "rs-chart-line",
  "rs-chart-line rs-chart-line-dashed",
  "rs-chart-line rs-chart-line-muted",
  "rs-chart-line rs-chart-line-dotted",
] as const;

export const MAX_SERIES = LINE_CLASS.length;

/** Crouwel-adjacent red. Applied only as an inline field variable, never in CSS. */
export const CROUWEL_SPOT = "#E30613";

export function niceMax(raw: number): number {
  if (raw <= 0) return 1;
  const pow = 10 ** Math.floor(Math.log10(raw));
  for (const f of [1, 2, 2.5, 5, 10]) {
    if (f * pow >= raw) return f * pow;
  }
  return 10 * pow;
}

export function defaultFormat(v: number, unit?: string): string {
  const n = Math.abs(v) >= 1000 ? `${+(v / 1000).toFixed(1)}k` : `${+v.toFixed(v % 1 === 0 ? 0 : 1)}`;
  return unit ? `${n} ${unit}` : n;
}

export function ticksFor(max: number, count = 4, inverted = false): number[] {
  const values = Array.from({ length: count }, (_, i) => ((i + 1) / count) * max);
  return inverted ? values.reverse() : values;
}

export function stackedRows(series: ChartSeries[]): number[][] {
  const n = Math.max(0, ...series.map((s) => s.values.length));
  return Array.from({ length: n }, (_, i) => {
    let sum = 0;
    return series.map((s) => {
      sum += s.values[i] ?? 0;
      return sum;
    });
  });
}

export function SrTable({
  caption,
  labels,
  series,
}: {
  caption: string;
  labels: string[];
  series: ChartSeries[];
}) {
  return (
    <table className="rs-sr">
      <caption>{caption}</caption>
      <thead>
        <tr>
          <th scope="col">Label</th>
          {series.map((s) => (
            <th key={s.name} scope="col">
              {s.name}
            </th>
          ))}
        </tr>
      </thead>
      <tbody>
        {labels.map((label, i) => (
          <tr key={i}>
            <th scope="row">{label}</th>
            {series.map((s) => (
              <td key={s.name}>{s.values[i]}</td>
            ))}
          </tr>
        ))}
      </tbody>
    </table>
  );
}

export function LegendSwatch({ seriesIndex, spot }: { seriesIndex: number; spot?: boolean }) {
  return (
    <svg width="18" height="4" viewBox="0 0 18 4" aria-hidden="true">
      <path d="M0 2h18" className={spot && seriesIndex === 0 ? "rs-chart-line rs-chart-line-spot" : LINE_CLASS[seriesIndex]} />
    </svg>
  );
}

export function ChartTip({
  left,
  top,
  label,
  rows,
}: {
  left: string;
  top: string;
  label: string;
  rows: Array<{ name?: string; value: string }>;
}) {
  return (
    <div className="rs-chart-tip" style={{ left, top }}>
      <span className="rs-chart-tip-label">{label}</span>
      {rows.map((row, i) => (
        <div key={i} className="rs-chart-tip-row">
          {row.name ? <span className="rs-chart-tip-name">{row.name}</span> : null}
          <span className="rs-chart-tip-val">{row.value}</span>
        </div>
      ))}
    </div>
  );
}

export interface ChartFieldProps extends React.HTMLAttributes<HTMLDivElement> {
  /** One Crouwel spot on the field. Chrome stays ink. */
  spot?: boolean | string;
}

export function ChartField({ spot, className, style, children, ...props }: ChartFieldProps) {
  const color = spot === true ? CROUWEL_SPOT : typeof spot === "string" ? spot : undefined;
  return (
    <div
      className={cx("rs-chart", "rs-chart-field", "rs-chart-enter", className)}
      style={{
        ...(style as React.CSSProperties),
        ...(color ? ({ ["--rs-chart-spot" as string]: color } as React.CSSProperties) : null),
      }}
      {...props}
    >
      {children}
    </div>
  );
}

export const PLOT = { W: 408, ML: 36, MR: 8, MT: 8, MB: 22 } as const;

/** Join class names, dropping falsy parts. */
export function cx(...parts: Array<string | false | null | undefined>): string {
  return parts.filter(Boolean).join(" ");
}

/* ── Charts: a poster field. Hairline grid, ink marks, no radius, no shadow.
   Chrome is monochrome. A field may set --rs-chart-spot (one Crouwel color).
   Series otherwise differ by texture, never a rainbow. ── */
.rs-chart{position:relative;width:100%;border-radius:0;box-shadow:none}
.rs-chart svg{display:block;width:100%;height:auto;overflow:visible}
.rs-chart-field{
  --rs-chart-spot:var(--text);
  isolation:isolate;
  background:var(--bg);
  border:1px solid var(--divider);
  border-radius:0;
  box-shadow:none;
  padding:16px;
}
.rs-chart-head{display:flex;justify-content:space-between;align-items:baseline;gap:12px;margin-bottom:10px}
.rs-chart-title{font-size:13px;font-weight:600;letter-spacing:-.01em;color:var(--text)}
.rs-chart-value{font-size:20px;font-weight:600;letter-spacing:-.02em;color:var(--text);font-variant-numeric:tabular-nums}
.rs-chart-grid{stroke:var(--divider-subtle);stroke-width:1}
.rs-chart-baseline{stroke:var(--divider);stroke-width:1}
.rs-chart-axis{fill:var(--text-secondary);font-size:11px;font-weight:500;letter-spacing:0;font-variant-numeric:tabular-nums}
.rs-chart-line{fill:none;stroke:var(--text);stroke-width:1;stroke-linecap:butt;stroke-linejoin:miter}
.rs-chart-line-dashed{stroke-dasharray:4 4}
.rs-chart-line-muted{stroke:var(--text-secondary)}
.rs-chart-line-dotted{stroke:var(--text-secondary);stroke-dasharray:0.1 5;stroke-width:1.5;stroke-linecap:butt}
.rs-chart-line-spot{stroke:var(--rs-chart-spot)}
.rs-chart-area{fill:var(--text);opacity:.08;stroke:none}
.rs-chart-area-spot{fill:var(--rs-chart-spot);opacity:.16;stroke:none}
.rs-chart-bar{fill:var(--text)}
.rs-chart-bar-muted{fill:var(--divider)}
.rs-chart-bar-spot{fill:var(--rs-chart-spot)}
.rs-chart-cursor{stroke:var(--divider);stroke-width:1}
.rs-chart-dot{fill:var(--bg);stroke:var(--text);stroke-width:1}
.rs-chart-mark{fill:var(--text)}
.rs-chart-mark-spot{fill:var(--rs-chart-spot)}
.rs-chart-ann{fill:var(--text-secondary);font-size:11px;font-weight:500;letter-spacing:-.01em}
.rs-chart-tip{
  position:absolute;pointer-events:none;
  background:var(--bg);border:1px solid var(--divider);
  border-radius:0;box-shadow:none;
  padding:6px 8px;font-size:12px;letter-spacing:-.01em;color:var(--text);
  white-space:nowrap;z-index:60;transform:translate(-50%,calc(-100% - 8px));
}
.rs-chart-tip-label{display:block;font-size:11px;color:var(--text-secondary);margin-bottom:2px}
.rs-chart-tip-row{display:flex;align-items:center;justify-content:space-between;gap:10px}
.rs-chart-tip-name{color:var(--text-secondary)}
.rs-chart-tip-val{font-weight:600;font-variant-numeric:tabular-nums}
.rs-chart-legend{display:flex;flex-wrap:wrap;gap:14px;margin-top:10px}
.rs-chart-legend-item{display:flex;align-items:center;gap:7px;font-size:12px;font-weight:500;letter-spacing:-.01em;color:var(--text-secondary)}
.rs-chart-legend-item svg{display:block}
.rs-chart-share{display:flex;height:8px;width:100%;border:1px solid var(--divider);border-radius:0}
.rs-chart-share-seg{height:100%;background:var(--text)}
.rs-chart-share-seg:nth-child(2){background:var(--text-secondary)}
.rs-chart-share-seg:nth-child(3){background:var(--divider)}
.rs-chart-share-seg-spot{background:var(--rs-chart-spot)}
.rs-chart-hist{fill:var(--text)}
.rs-chart-donut{display:block}
.rs-chart-donut-track{fill:none;stroke:var(--divider);stroke-width:1}
.rs-chart-donut-value{fill:none;stroke:var(--rs-chart-spot);stroke-width:1;stroke-linecap:butt}
.rs-chart-donut-label{fill:var(--text);font-size:16px;font-weight:600;letter-spacing:-.02em;font-variant-numeric:tabular-nums}
.rs-chart-donut-caption{fill:var(--text-secondary);font-size:11px;font-weight:500}
.rs-chart-multi{display:grid;grid-template-columns:repeat(auto-fill,minmax(184px,1fr));gap:20px}
.rs-chart-multi-cap{margin:0 0 8px;font-size:12px;font-weight:600;letter-spacing:-.01em;color:var(--text)}
.rs-chart-multi .rs-chart-field{padding:12px}
